// ── Intent Detection + URL Resolution ─────────────────────────────────────
// Input : { body: { message, page, context: { lastCollaborateurId, lastIntent, ... } } }
// Output: { message, intent, apiUrl, context, collaborateurId, isFollowUp }

const body = ($input.first().json.body) || {};
const raw  = (body.message || '').trim();
const msg  = raw.toLowerCase();
const ctx  = body.context || {};
const page = (body.page || '').toLowerCase();

// ── Intent table (priority order) ──────────────────────────────────────────
const INTENTS = [
  {
    intent: 'SUCCESSION',
    kw: ['rempla\u00e7ant','remplacer','succession','successeur','backup','d\u00e9part de','qui remplace','qui peut remplacer','candidat successeur','plan de succession']
  },
  {
    intent: 'TALENT',
    kw: ['haut potentiel','hauts potentiels','high potential','hipo','top talent','top talents','nine box','9 box','fort potentiel','meilleur profil','best performer','star','matrice talent']
  },
  {
    intent: 'PROMOTION',
    kw: ['promotion','promouvable','pr\u00eat \u00e0 \u00e9voluer','carri\u00e8re','\u00e9volution','readiness','monter en grade','passer manager','acc\u00e9der \u00e0','qui m\u00e9rite','\u00e9voluer']
  },
  {
    intent: 'FORMATION',
    kw: ['formation','certification','d\u00e9veloppement','parcours','comp\u00e9tence manquante','formation recommand\u00e9e','apprendre','se former','udemy','coursera','plan de d\u00e9veloppement']
  },
  {
    intent: 'POSTES_CRITIQUES',
    kw: ['sans successeur','poste critique','poste \u00e0 risque','risque succession','risque rh','position critique','vuln\u00e9rabilit\u00e9']
  },
  {
    intent: 'ANALYTICS',
    kw: ['statistique','stats','kpi','effectif','r\u00e9partition','insights rh','tableau de bord','combien','taux','distribution','dashboard']
  }
];

// Default: page context
let intent = 'ANALYTICS';
if (page.includes('succession')) intent = 'SUCCESSION';
else if (page.includes('talent')) intent = 'TALENT';
else if (page.includes('formation')) intent = 'FORMATION';

// Follow-up detection (reuse last intent)
const followUpKw = ['et lui','et elle','et son','et ses','pourquoi lui','pourquoi elle','et son readiness','et ses formations','le m\u00eame','et ses comp\u00e9tences','et la succession','son rempl\u00e7ant'];
const isFollowUp = followUpKw.some(kw => msg.includes(kw));
if (isFollowUp && ctx.lastIntent) {
  intent = ctx.lastIntent;
} else {
  for (const { intent: i, kw } of INTENTS) {
    if (kw.some(k => msg.includes(k))) { intent = i; break; }
  }
}

// ── API URL Resolution ──────────────────────────────────────────────────────
const BASE = 'http://localhost:5000/api/chatbot';
const cid  = body.contextId || (ctx && ctx.lastCollaborateurId) || null;
let apiUrl = BASE + '/stats';

if      (intent === 'TALENT')          apiUrl = BASE + '/hr-talent';
else if (intent === 'PROMOTION')       apiUrl = BASE + '/promotables';
else if (intent === 'POSTES_CRITIQUES') apiUrl = BASE + '/postes-a-risque';
else if (intent === 'SUCCESSION')      apiUrl = cid ? (BASE + '/succession/' + cid) : (BASE + '/postes-sans-successeur');

return [{ json: { message: raw, intent, apiUrl, context: ctx, collaborateurId: cid, isFollowUp } }];

// ── Format Reply — Unified HR Copilot Response ────────────────────────────
// Reads:  $('Detect Intent').first().json → intent, context, collaborateurId
//         $input.first().json             → SIRH API response data
// Output: { answer, analysis, reasoning, actions, suggestions, sources, cards, executionHistory, context }

const di   = $('Detect Intent').first().json;
const intent = di.intent;
const ctx    = di.context || {};
const cid    = di.collaborateurId;
const data   = $input.first().json;
const now    = new Date().toISOString();

// ── Build execution history (last 10) ──────────────────────────────────────
const prevHistory = Array.isArray(ctx.executionHistory) ? ctx.executionHistory : [];
const execEntry   = {
  timestamp:   now,
  intent,
  endpoint:    di.apiUrl,
  resultCount: (typeof data.total === 'number') ? data.total :
               Array.isArray(data) ? data.length : 1
};
const executionHistory = [...prevHistory, execEntry].slice(-10);

// ── Shared context carrier ─────────────────────────────────────────────────
const newCtx = Object.assign({}, ctx, { lastIntent: intent, executionHistory });

let answer = '', analysis = '', reasoning = [], actions = [], suggestions = [], sources = [], cards = [];

// ════════════════════════════════════════════════════════════════════════════
// TALENT
// ════════════════════════════════════════════════════════════════════════════
if (intent === 'TALENT') {
  const talents = Array.isArray(data) ? data : [];
  const top     = talents[0];

  answer   = talents.length > 0
    ? talents.length + ' haut(s) potentiel(s) identifi\u00e9(s) dans l\'organisation.'
    : 'Aucun haut potentiel identifi\u00e9 avec le seuil actuel (\u2265\u202f4/5).';

  analysis = top
    ? 'Meilleur profil\u00a0: ' + top.Nom + ' (' + top.Grade + ', ' + top.Departement + ') — score ' + top.MoyenneCompetences + '/5.'
    : '';

  reasoning = [
    'Seuil haut potentiel\u00a0: moyenne comp\u00e9tences \u2265 4.0/5',
    talents.length + ' collaborateur(s) atteignent ce seuil',
    top ? 'Score maximum\u00a0: ' + top.MoyenneCompetences + '/5 \u2014 ' + top.Nom : 'Aucun collaborateur au-dessus du seuil',
    'Calcul automatis\u00e9 sur les \u00e9valuations de comp\u00e9tences enregistr\u00e9es'
  ];

  actions     = ['Voir la matrice 9-Box', 'Planifier une revue talent', 'Lancer un plan de succession'];
  suggestions = ['Qui est pr\u00eat pour une promotion ?', 'Quels postes sont sans successeur ?', 'Montrez les postes \u00e0 risque'];
  sources     = [{ label: 'GET /api/chatbot/hr-talent', type: 'api' }];

  cards = talents.slice(0, 5).map(function(t, i) {
    return {
      type: 'collaborateur',
      rank: i + 1,
      data: {
        nom:         t.Nom,
        grade:       t.Grade,
        departement: t.Departement,
        score:       t.MoyenneCompetences,
        badge:       t.MoyenneCompetences >= 4.5 ? 'Talent strat\u00e9gique' : 'Haut potentiel'
      }
    };
  });

  if (top) { newCtx.lastCollaborateurNom = top.Nom; }
}

// ════════════════════════════════════════════════════════════════════════════
// SUCCESSION
// ════════════════════════════════════════════════════════════════════════════
else if (intent === 'SUCCESSION') {
  if (cid && data.top3) {
    const top3    = data.top3 || [];
    const partant = data.collaborateurNom || 'ce collaborateur';

    answer   = top3.length > 0
      ? top3.length + ' successeur(s) identifi\u00e9(s) pour ' + partant + '.'
      : 'Aucun successeur identifi\u00e9 pour ' + partant + '.';

    analysis = top3[0]
      ? 'Meilleur successeur\u00a0: ' + top3[0].nom + ' (' + top3[0].grade + ', ' + top3[0].departement + ') \u2014 ' + top3[0].scoreMatch + '% de compatibilit\u00e9.'
      : 'Aucun profil compatible.';

    reasoning = [
      'Poste analys\u00e9\u00a0: ' + (data.poste || ''),
      (data.competencesRequises || []).length + ' comp\u00e9tence(s) \u00e9valu\u00e9e(s)',
      'Score de matching = comp\u00e9tences communes / comp\u00e9tences requises \u00d7 100',
      top3.some(function(t) { return t.profilTransversal; }) ? 'Profil(s) transversal(aux) valoris\u00e9(s) en priorit\u00e9' : 'Profils tri\u00e9s par nb de comp\u00e9tences communes'
    ];

    actions     = ['Voir le plan de succession complet', 'Exporter la comparaison PDF', 'Planifier un entretien'];
    suggestions = [
      'Quels postes sont sans successeur ?',
      top3[0] ? 'Quel est le readiness de ' + top3[0].nom + ' ?' : 'Montrez les postes \u00e0 risque',
      'Quelles formations recommandez-vous ?'
    ];
    sources = [{ label: 'GET /api/chatbot/succession/' + cid, type: 'api' }];

    cards = [{
      type: 'succession',
      data: {
        partant:   partant,
        poste:     data.poste,
        candidats: top3.map(function(c, i) {
          return {
            rank:                  i + 1,
            nom:                   c.nom,
            poste:                 c.poste,
            grade:                 c.grade,
            departement:           c.departement,
            scoreMatch:            c.scoreMatch,
            competencesManquantes: c.competencesManquantes || [],
            profilTransversal:     c.profilTransversal,
            delaiEstime:           c.scoreMatch >= 80 ? '3\u20136 mois' : c.scoreMatch >= 50 ? '6\u201312 mois' : '12\u201318 mois'
          };
        })
      }
    }];

    if (top3[0]) { newCtx.lastCollaborateurId = top3[0].id; newCtx.lastCollaborateurNom = top3[0].nom; }

  } else {
    // Postes sans successeur
    const critiques = data.collaborateurs || [];

    answer   = critiques.length > 0
      ? critiques.length + ' poste(s) sans successeur identifi\u00e9(s).'
      : 'Tous les postes cl\u00e9s disposent d\'un successeur potentiel.';

    reasoning = [
      'Crit\u00e8re\u00a0: aucun candidat avec \u2265 50% de couverture des comp\u00e9tences',
      critiques.length + ' poste(s) en situation critique',
      critiques[0] ? 'Poste le plus expos\u00e9\u00a0: ' + critiques[0].nom + ' \u2014 ' + (critiques[0].poste || '') : ''
    ].filter(function(s) { return !!s; });

    actions     = ['Identifier des successeurs', 'Lancer un plan de d\u00e9veloppement', 'Voir les formations recommand\u00e9es'];
    suggestions = ['Montrez les postes \u00e0 risque', 'Quels sont les hauts potentiels ?'];
    sources     = [{ label: 'GET /api/chatbot/postes-sans-successeur', type: 'api' }];

    cards = critiques.slice(0, 5).map(function(c) {
      return {
        type: 'collaborateur',
        rank: null,
        data: {
          nom:         c.nom,
          poste:       c.poste,
          grade:       c.grade,
          departement: c.departement,
          badge:       'Sans successeur',
          badgeLevel:  'critical'
        }
      };
    });
  }
}

// ════════════════════════════════════════════════════════════════════════════
// PROMOTION
// ════════════════════════════════════════════════════════════════════════════
else if (intent === 'PROMOTION') {
  const promo = data.collaborateurs || [];
  const top   = promo[0];

  answer   = promo.length > 0
    ? promo.length + ' collaborateur(s) pr\u00eat(s) pour une promotion.'
    : 'Aucun collaborateur n\'atteint le seuil de promotabilit\u00e9 actuel (score \u2265 4/5).';

  analysis = top
    ? 'Profil le plus pr\u00eat\u00a0: ' + top.nom + ' (' + top.grade + ', ' + top.departement + ') \u2014 Score\u00a0: ' + top.score + '/5.'
    : '';

  reasoning = [
    'Crit\u00e8re de promotabilit\u00e9\u00a0: score moyen comp\u00e9tences \u2265 4.0/5',
    promo.length + ' collaborateur(s) atteignent ce seuil',
    top ? 'Premier candidat\u00a0: ' + top.nom + ' avec un score de ' + top.score + '/5' : 'Aucun profil \u00e9ligible',
    'Simulation avanc\u00e9e disponible dans RH Insights \u2192 Simulateur Promotion'
  ];

  actions     = ['Simuler la readiness promotion', 'Voir le parcours carri\u00e8re', 'Planifier un entretien de carri\u00e8re'];
  suggestions = [
    top ? 'Quel est le readiness de ' + top.nom + ' pour le prochain grade ?' : 'Montrez les hauts potentiels',
    'Quelles comp\u00e9tences manquent pour la promotion ?',
    'Quelles formations recommandez-vous ?'
  ];
  sources = [{ label: 'GET /api/chatbot/promotables', type: 'api' }];

  cards = promo.slice(0, 5).map(function(p, i) {
    return {
      type: 'promotion',
      rank: i + 1,
      data: {
        nom:           p.nom,
        poste:         p.poste,
        grade:         p.grade,
        departement:   p.departement,
        score:         p.score,
        readinessLabel: p.score >= 4.5 ? 'Tr\u00e8s pr\u00eat' : 'Pr\u00eat'
      }
    };
  });

  if (top) { newCtx.lastCollaborateurId = top.id; newCtx.lastCollaborateurNom = top.nom; }
}

// ════════════════════════════════════════════════════════════════════════════
// POSTES CRITIQUES
// ════════════════════════════════════════════════════════════════════════════
else if (intent === 'POSTES_CRITIQUES') {
  const risques = data.collaborateurs || [];
  const eleve   = risques.filter(function(r) { return r.niveauRisque === '\u00c9lev\u00e9'; });
  const moyen   = risques.filter(function(r) { return r.niveauRisque === 'Moyen'; });

  answer = risques.length > 0
    ? risques.length + ' poste(s) \u00e0 risque d\u00e9tect\u00e9(s) \u2014 ' + eleve.length + ' risque \u00e9lev\u00e9, ' + moyen.length + ' risque moyen.'
    : 'Aucun poste \u00e0 risque d\u00e9tect\u00e9. Les niveaux de comp\u00e9tences sont align\u00e9s avec les attentes par grade.';

  reasoning = [
    'Seuils par grade\u00a0: Junior=2.0, Senior=3.0, Manager=3.5, Director/SM=4.0, Partner=4.5',
    'Risque \u00e9lev\u00e9\u00a0: score < seuil ET anciennet\u00e9 > 2 ans',
    'Risque moyen\u00a0: score < seuil (anciennet\u00e9 \u2264 2 ans)',
    eleve.length + ' poste(s) en risque \u00e9lev\u00e9 identifi\u00e9(s)'
  ];

  actions     = ['Lancer un plan de d\u00e9veloppement', 'Planifier des \u00e9valuations', 'Voir les formations prioritaires'];
  suggestions = ['Qui peut remplacer ces collaborateurs ?', 'Quelles formations recommandez-vous ?', 'Montrez les hauts potentiels'];
  sources     = [{ label: 'GET /api/chatbot/postes-a-risque', type: 'api' }];

  cards = risques.slice(0, 5).map(function(r) {
    return {
      type: 'alerte',
      data: {
        nom:          r.nom,
        poste:        r.poste,
        grade:        r.grade,
        departement:  r.departement,
        scoreActuel:  r.scoreActuel,
        seuilAttendu: r.seuilAttendu,
        ecart:        r.ecart,
        niveauRisque: r.niveauRisque,
        anciennete:   r.anciennete
      }
    };
  });
}

// ════════════════════════════════════════════════════════════════════════════
// FORMATION
// ════════════════════════════════════════════════════════════════════════════
else if (intent === 'FORMATION') {
  const s = data;
  answer   = (s.formationsEnCours || 0) + ' formation(s) en cours \u2014 Taux de compl\u00e9tion global\u00a0: ' + (s.tauxCompletion || 0) + '%.';
  analysis = 'Sur ' + (s.totalInscriptions || 0) + ' inscriptions, ' + (s.terminees || 0) + ' formations sont termin\u00e9es.';

  reasoning = [
    (s.formationsEnCours || 0) + ' formation(s) actuellement en cours',
    (s.terminees || 0) + ' formation(s) compl\u00e9t\u00e9e(s)',
    'Taux de compl\u00e9tion global\u00a0: ' + (s.tauxCompletion || 0) + '%',
    'Recommandations personnalis\u00e9es disponibles dans le module Formation'
  ];

  actions     = ['Voir le catalogue de formations', 'Acc\u00e9der aux recommandations', 'Voir les certifications'];
  suggestions = ['Quelles formations recommandez-vous ?', 'Montrez les comp\u00e9tences manquantes', 'Taux de compl\u00e9tion par d\u00e9partement'];
  sources     = [{ label: 'GET /api/chatbot/stats', type: 'api' }];

  cards = [{
    type: 'analytics',
    data: {
      kpis: [
        { label: 'Formations en cours',  value: s.formationsEnCours  || 0, icon: 'fa-book' },
        { label: 'Formations termin\u00e9es', value: s.terminees          || 0, icon: 'fa-check-circle' },
        { label: 'Total inscriptions',    value: s.totalInscriptions  || 0, icon: 'fa-user-graduate' },
        { label: 'Taux de compl\u00e9tion',   value: (s.tauxCompletion || 0) + '%', icon: 'fa-chart-pie' }
      ]
    }
  }];
}

// ════════════════════════════════════════════════════════════════════════════
// ANALYTICS (default)
// ════════════════════════════════════════════════════════════════════════════
else {
  const s     = data;
  const top5D = (s.repartitionDept   || []).slice(0, 5);
  const top5C = (s.topCompetences    || []).slice(0, 5);

  answer = 'Organisation\u00a0: ' + (s.collaborateursActifs || 0) + ' collaborateur(s) actif(s) \u2014 ' +
    (s.formationsEnCours || 0) + ' formation(s) en cours \u2014 Taux de compl\u00e9tion\u00a0: ' + (s.tauxCompletion || 0) + '%.';

  reasoning = [
    'Source\u00a0: donn\u00e9es SIRH EY en temps r\u00e9el',
    (s.collaborateursActifs || 0) + ' collaborateur(s) actif(s) dans le syst\u00e8me',
    (s.formationsEnCours || 0) + ' formation(s) actuellement en cours',
    'Taux de compl\u00e9tion global\u00a0: ' + (s.tauxCompletion || 0) + '%'
  ];

  actions     = ['Voir le tableau de bord RH', 'Acc\u00e9der aux insights', 'Exporter un rapport'];
  suggestions = ['Quels sont les hauts potentiels ?', 'Qui est pr\u00eat pour une promotion ?', 'Quels postes sont sans successeur ?'];
  sources     = [{ label: 'GET /api/chatbot/stats', type: 'api' }];

  cards = [{
    type: 'analytics',
    data: {
      kpis: [
        { label: 'Collaborateurs actifs', value: s.collaborateursActifs || 0, icon: 'fa-users' },
        { label: 'Formations en cours',   value: s.formationsEnCours   || 0, icon: 'fa-book' },
        { label: 'Taux de compl\u00e9tion',   value: (s.tauxCompletion || 0) + '%', icon: 'fa-chart-pie' },
        { label: 'Termin\u00e9es',            value: s.terminees           || 0, icon: 'fa-check-circle' }
      ],
      departments:     top5D.map(function(d) { return { label: d.departement, value: d.total }; }),
      topCompetences:  top5C.map(function(c) { return { label: c.nom, value: c.niveauMoyen, count: c.nbCollaborateurs }; })
    }
  }];
}

return [{
  json: {
    answer,
    analysis:  analysis  || null,
    reasoning: reasoning.filter(Boolean),
    actions,
    suggestions,
    sources,
    cards,
    executionHistory,
    context: newCtx
  }
}];
